test_cases.assertion_pseudocode:
from core.config import RoutingConfig
from pydantic import ValidationError
try:
    RoutingConfig(assessor_model='')
    assert False, 'Should raise ValidationError'
except ValidationError as e:
    assert 'assessor_model' in str(e)
try:
    RoutingConfig(confidence_threshold=1.5)
    assert False, 'Should raise ValidationError'
except ValidationError as e:
    assert 'confidence_threshold' in str(e)

edge_case_tests.assertion_pseudocode:
from core.config import RoutingConfig
from pydantic import ValidationError
for bad_threshold in [1.5, -0.1, 2.0]:
    try:
        config = RoutingConfig(confidence_threshold=bad_threshold)
        assert False, f'ValidationError should have been raised for {bad_threshold}'
    except ValidationError as e:
        error_fields = [err['loc'] for err in e.errors()]
        assert any('confidence_threshold' in str(loc) for loc in error_fields), f'Field not mentioned for {bad_threshold}'
